// Typed client for the AkkiaBot HTTP API (types generated by `just gen-api`).
import createClient from "openapi-fetch";
import type { paths } from "./schema";
import type { CaptchaErrorCode, CaptchaVerifyRequest } from "./types";

export type ApiClient = ReturnType<typeof createApiClient>;

export type FetchFn = (request: Request) => Promise<Response>;

export function createApiClient(baseUrl: string, fetchImpl?: FetchFn) {
  return createClient<paths>({
    baseUrl,
    // Resolve `fetch` lazily so tests can stub the global after the client is built.
    fetch: (request) => (fetchImpl ?? globalThis.fetch)(request),
  });
}

export type VerifyResult =
  | { ok: true; message: string }
  | { ok: false; kind: "rejected"; code: CaptchaErrorCode; message: string; status: number }
  | { ok: false; kind: "network" }
  | { ok: false; kind: "unexpected"; status: number };

const KNOWN_CODES: ReadonlySet<string> = new Set<CaptchaErrorCode>([
  "captcha_unavailable",
  "turnstile_failed",
  "init_data_invalid",
  "init_data_expired",
  "challenge_not_found",
  "challenge_expired",
  "challenge_used",
  "wrong_user",
  "not_captcha_restricted",
  "unmute_failed",
]);

function isCaptchaError(value: unknown): value is { error: CaptchaErrorCode; message: string } {
  if (typeof value !== "object" || value === null) return false;
  const { error, message } = value as Record<string, unknown>;
  return typeof error === "string" && KNOWN_CODES.has(error) && typeof message === "string";
}

/** `POST /api/v1/captcha/verify`; never throws. */
export async function verifyCaptcha(
  client: ApiClient,
  body: CaptchaVerifyRequest,
): Promise<VerifyResult> {
  let result: Awaited<ReturnType<ApiClient["POST"]>>;
  try {
    result = await client.POST("/api/v1/captcha/verify", { body });
  } catch {
    return { ok: false, kind: "network" };
  }
  const { data, error, response } = result;
  if (data) return { ok: true, message: data.message };
  if (isCaptchaError(error)) {
    return {
      ok: false,
      kind: "rejected",
      code: error.error,
      message: error.message,
      status: response.status,
    };
  }
  return { ok: false, kind: "unexpected", status: response.status };
}
